int main() {
    string input;
    getline(cin, input);
    stack<string> stk;
​
    stk.push("");
    for (char c : input) {
        // 压入一个新字符串，处理括号问题
        if (c == '(') {
            stk.push("");
        // 一个括号结束，反转栈顶元素    
        } else if (c == ')') {
            string tmp = stk.top();
            stk.pop();
            reverse(tmp.begin(), tmp.end());

            string top = stk.top();
            stk.pop();
            stk.push(top + tmp);
        // 直接追加到栈顶元素    
        } else {
            string top = stk.top();
            stk.pop();
            stk.push(top + c);
        }
    }
​
    cout << stk.top();
​
    return 0;
}

