public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();  // 读取输入
        Stack<String> stk = new Stack<>();
​
        stk.push("");
        for (char c : input.toCharArray()) {
            // 压入一个新字符串，处理括号问题
            if (c == '(') {
                stk.push("");
            } else if (c == ')') {
                String tmp = stk.pop();
                tmp = new StringBuilder(tmp).reverse().toString();  // 反转栈顶元素
​
                String top = stk.pop();
                stk.push(top + tmp);
            } else {
                // 直接追加到栈顶元素
                String top = stk.pop();
                stk.push(top + c);
            }
        }
​
        System.out.println(stk.peek());
    }
}
