function main(input) {
    const stk = [""];

    for (let c of input) {
        // 压入一个新字符串，处理括号问题
        if (c === '(') {
            stk.push("");
        } else if (c === ')') {
            let tmp = stk.pop();
            tmp = tmp.split("").reverse().join("");  // 反转栈顶元素

            let top = stk.pop();
            stk.push(top + tmp);
        } else {
            // 直接追加到栈顶元素
            let top = stk.pop();
            stk.push(top + c);
        }
    }

    console.log(stk[stk.length - 1]);
}
