package main
​
import (
    "bufio"
    "fmt"
    "os"
)
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    input := scanner.Text() // 读取输入
    var stk []string
​
    stk = append(stk, "")
    for _, c := range input {
        // 压入一个新字符串，处理括号问题
        if c == '(' {
            stk = append(stk, "")
        } else if c == ')' {
            tmp := stk[len(stk)-1]
            stk = stk[:len(stk)-1]
            // 反转栈顶元素
            tmp = reverse(tmp)

            top := stk[len(stk)-1]
            stk = stk[:len(stk)-1]
            stk = append(stk, top+tmp)
        } else {
            // 直接追加到栈顶元素
            top := stk[len(stk)-1]
            stk = stk[:len(stk)-1]
            stk = append(stk, top+string(c))
        }
    }
​
    fmt.Println(stk[len(stk)-1])
}
​
// 反转字符串的辅助函数
func reverse(s string) string {
    result := []rune(s)
    for i, j := 0, len(result)-1; i < j; i, j = i+1, j-1 {
        result[i], result[j] = result[j], result[i]
    }
    return string(result)
}
